namespace Vesper.MediaResolver.Models;

public sealed record AudioTrack(string Id, string? Language, string? Name, bool IsDefault = false, int? Channels = null, string? Codec = null);

/// <summary>A source-provided subtitle, not an inferred language or generated track.</summary>
/// <param name="Url">Authorized HTTP(S) subtitle address.</param>
/// <param name="Language">Source language tag.</param>
/// <param name="Name">Optional source-provided display name.</param>
/// <param name="IsAutoGenerated">Whether the source identifies this track as automatic captions.</param>
/// <param name="Format">vtt, srt, ttml, hls-webvtt (playlist of WebVTT segments) ...</param>
public sealed record SubtitleTrack(Uri Url, string Language, string? Name, string Format, bool IsAutoGenerated = false);

public sealed record Chapter(string Title, TimeSpan Start, TimeSpan? End = null);

/// <summary>Describes a collection related to a single item, without enumerating it.</summary>
public sealed record CollectionHint(CollectionKind Kind, string? Id, Uri Url, bool IsDynamic, string? Title);

/// <summary>A single resolved video or audio item.</summary>
public sealed record MediaItem
{
    public required Uri SourceUrl { get; init; }
    public required string Provider { get; init; }
    public string? MediaId { get; init; }
    public string Title { get; init; } = "";
    public string? Description { get; init; }
    public string? Uploader { get; init; }
    public TimeSpan? Duration { get; init; }
    public Uri? Thumbnail { get; init; }
    public MediaKind Kind { get; init; } = MediaKind.Video;
    public bool IsLive { get; init; }

    public IReadOnlyList<MediaRepresentation> Representations { get; init; } = [];
    public IReadOnlyList<AudioTrack> AudioTracks { get; init; } = [];
    public IReadOnlyList<SubtitleTrack> Subtitles { get; init; } = [];
    public IReadOnlyList<Chapter> Chapters { get; init; } = [];

    /// <summary>Set when the URL also referenced a collection (e.g. YouTube list=). The collection is NOT enumerated.</summary>
    public CollectionHint? Related { get; init; }

    /// <summary>Earliest known expiry among all representations (temporary signed URLs).</summary>
    public DateTimeOffset? EarliestExpiry
    {
        get
        {
            DateTimeOffset? min = null;
            foreach (var r in Representations)
                if (r.ExpiresAt is { } e && (min is null || e < min)) min = e;
            return min;
        }
    }
}
